MODULES_JS = '/* ===== js/features/guest.js ===== */\n/* =========================================================================\n * Nodalis - features/guest.js\n *\n * THE SHARED-NOTE READER.\n *\n * A published note used to be a link to a Gist, which meant the person you\n * sent it to landed on github.com looking at a raw file with GitHub\'s chrome\n * around it. It worked, and it was clearly somebody else\'s product.\n *\n * Now the link points at Nodalis itself:\n *\n *     https://your-site/#/share/<gist-id>\n *\n * and the app recognises that on load and comes up in GUEST MODE: the note,\n * rendered by the same markdown engine and wearing the same themes, with the\n * Nodalis name on it, an install button, and a way for the reader to start\n * their own vault. No sidebar, no editor, no vault, no prompts.\n *\n * HOW IT AVOIDS THE APP ENTIRELY\n * Guest mode is decided BEFORE boot() runs and boot() is never called. It does\n * not open the database, restore a folder, or start a single feature module -\n * so there is no first-run dialog, no install card, no tour and no vault. It\n * uses exactly three things from the app: the stylesheet, the icon set and the\n * markdown renderer. That isolation is the whole design: nothing a guest does\n * can touch anybody\'s notes, because in guest mode the notes layer never\n * exists.\n *\n * WHAT THE GUEST CONTROLS, AND WHAT THEY DO NOT\n * They choose the theme and light or dark, and that choice is stored under its\n * own localStorage key. It is never sent anywhere and it has no relationship\n * to the author\'s settings - the author\'s theme is the author\'s business, and\n * a reader in a dark room should not have to accept a light page.\n *\n * They cannot edit. Not "the editor is hidden" - there is no editor on the\n * page. The content is rendered HTML.\n *\n * STAYING CURRENT\n * The note is fetched on load, whenever the tab regains focus, and on demand.\n * When the author publishes again, the reader sees it - no reload needed. If\n * the content has changed since they opened it, that is announced rather than\n * swapped underneath them mid-sentence.\n *\n * ON PRIVACY, HONESTLY\n * The gist is created unlisted, and the author\'s notes repository stays\n * private - publishing one note never exposes the vault. But "unlisted" is not\n * "private": anyone holding the link can read it, which is true of every share\n * link ever made, and the publish dialog says so plainly.\n * ========================================================================= */\n(function (N) {\n  \'use strict\';\n\n  const ROUTE = /#\\/?share\\/([A-Za-z0-9]+)/;\n  const PREF_KEY = \'nodalis.guest.prefs\';\n  const STYLES = [\'nodalis\', \'notion\', \'nothing\', \'slate\', \'aurora\', \'terminal\'];\n  const STYLE_LABELS = {\n    nodalis: \'Nodalis\', notion: \'Paper\', nothing: \'Nothing\',\n    slate: \'Slate\', aurora: \'Schematic\', terminal: \'Terminal\',\n  };\n  /* Kept in step with the app\'s own signature accents. */\n  const SIGNATURE = { nothing: \'#d71921\', terminal: \'#0f7a4a\' };\n\n  let gistId = null;\n  let doc = null;               // { title, markdown, updatedAt, files }\n  let lastFetchedText = null;\n  let root = null;\n\n  /* ------------------------------------------------------------------ route */\n\n  function wanted() {\n    try { return ROUTE.test(String(location.hash || \'\')); }\n    catch (err) { return false; }\n  }\n\n  function idFromHash() {\n    const m = ROUTE.exec(String(location.hash || \'\'));\n    return m ? m[1] : null;\n  }\n\n  /** The base the app is served from, which is what a share link points at. */\n  function appBase() {\n    return location.origin + location.pathname;\n  }\n\n  function linkFor(id) {\n    return appBase() + \'#/share/\' + id;\n  }\n\n  /* ------------------------------------------------------------ preferences */\n\n  function prefs() {\n    try {\n      const raw = localStorage.getItem(PREF_KEY);\n      const parsed = raw ? JSON.parse(raw) : {};\n      return {\n        style: STYLES.indexOf(parsed.style) !== -1 ? parsed.style : \'nodalis\',\n        mode: parsed.mode === \'dark\' ? \'dark\' : (parsed.mode === \'light\' ? \'light\' : \'auto\'),\n        width: parsed.width === \'wide\' ? \'wide\' : \'comfortable\',\n      };\n    } catch (err) {\n      return { style: \'nodalis\', mode: \'auto\', width: \'comfortable\' };\n    }\n  }\n\n  function savePrefs(patch) {\n    const next = Object.assign(prefs(), patch || {});\n    try { localStorage.setItem(PREF_KEY, JSON.stringify(next)); }\n    catch (err) { /* a private window just gets the default next time */ }\n    applyPrefs();\n    return next;\n  }\n\n  function resolveMode(mode) {\n    if (mode === \'dark\' || mode === \'light\') return mode;\n    try {\n      return window.matchMedia(\'(prefers-color-scheme: dark)\').matches ? \'dark\' : \'light\';\n    } catch (err) { return \'light\'; }\n  }\n\n  /**\n   * The theme applied without the theme module, because the theme module reads\n   * the settings store and in guest mode there is no store. All the stylesheet\n   * actually needs is data-style and data-mode; the two single-hue themes also\n   * carry their accent inline, which is what the app does.\n   */\n  function applyPrefs() {\n    const p = prefs();\n    const mode = resolveMode(p.mode);\n    [document.documentElement, document.body].forEach(function (host) {\n      if (!host) return;\n      host.dataset.style = p.style;\n      host.dataset.mode = mode;\n    });\n    document.documentElement.dataset.contentWidth = p.width;\n    if (SIGNATURE[p.style]) document.documentElement.style.setProperty(\'--accent\', SIGNATURE[p.style]);\n    else document.documentElement.style.removeProperty(\'--accent\');\n    const label = document.getElementById(\'nd-guest-theme-label\');\n    if (label) label.textContent = STYLE_LABELS[p.style] || p.style;\n  }\n\n  /* --------------------------------------------------------------- fetching */\n\n  /**\n   * Unauthenticated read of a gist by id. This is what makes the reader work\n   * for someone with no GitHub account and no token - the link is enough.\n   */\n  async function fetchNote(id) {\n    const res = await fetch(\'https://api.github.com/gists/\' + encodeURIComponent(id), {\n      headers: { Accept: \'application/vnd.github+json\' },\n      cache: \'no-store\',\n    });\n    if (res.status === 404) {\n      const err = new Error(\'This note is no longer shared. The person who sent it may have taken it down.\');\n      err.code = \'gone\';\n      throw err;\n    }\n    if (res.status === 403) {\n      const err = new Error(\'GitHub is rate-limiting this network for the moment. Try again in a few minutes.\');\n      err.code = \'rate\';\n      throw err;\n    }\n    if (!res.ok) throw new Error(\'Could not load the note (GitHub replied \' + res.status + \').\');\n    const json = await res.json();\n    const files = json.files || {};\n    const name = Object.keys(files)[0];\n    if (!name) throw new Error(\'That share link points at something empty.\');\n    const file = files[name];\n\n    let content = file.content;\n    // A gist over a megabyte comes back truncated, with a raw_url to fetch.\n    if (file.truncated && file.raw_url) {\n      const raw = await fetch(file.raw_url, { cache: \'no-store\' });\n      if (raw.ok) content = await raw.text();\n    }\n    const title = String(name).replace(/\\.md$/i, \'\');\n    return {\n      title: title,\n      markdown: dropDuplicateTitle(stripFrontMatter(String(content || \'\')), title),\n      updatedAt: Date.parse(json.updated_at || \'\') || Date.now(),\n      owner: (json.owner && json.owner.login) || \'\',\n    };\n  }\n\n  /** Front matter is the author\'s plumbing, not the reader\'s business. */\n  function stripFrontMatter(text) {\n    const m = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---\\r?\\n?/.exec(text);\n    return m ? text.slice(m[0].length) : text;\n  }\n\n  /*\n   * Almost every note starts with an H1 repeating its own title, because that\n   * is how markdown works. The reader already prints the title in the header,\n   * so leaving the H1 in shows the same words twice in two different sizes.\n   * Dropped only when it genuinely matches - a note whose first heading says\n   * something else keeps it.\n   */\n  function dropDuplicateTitle(markdown, title) {\n    const text = String(markdown || \'\').replace(/^\\s*\\n/, \'\');\n    const m = /^#\\s+(.+?)\\s*(?:\\r?\\n|$)/.exec(text);\n    if (!m) return markdown;\n    const heading = m[1].trim().toLowerCase();\n    const wanted = String(title || \'\').trim().toLowerCase();\n    if (!heading || heading !== wanted) return markdown;\n    return text.slice(m[0].length).replace(/^\\s*\\n/, \'\');\n  }\n\n  /* ----------------------------------------------------------------- markup */\n\n  function el(tag, attrs, text) {\n    const parts = String(tag).split(/(?=[.#])/);\n    const node = document.createElement(parts[0] || \'div\');\n    parts.slice(1).forEach(function (p) {\n      if (p[0] === \'.\') node.classList.add(p.slice(1));\n      else if (p[0] === \'#\') node.id = p.slice(1);\n    });\n    Object.keys(attrs || {}).forEach(function (k) {\n      if (k === \'style\') Object.assign(node.style, attrs[k]);\n      else node.setAttribute(k, attrs[k]);\n    });\n    if (text !== undefined && text !== null) node.textContent = String(text);\n    return node;\n  }\n\n  function icon(name, size) {\n    try { return N.icons.node(name, { size: size || 16 }); }\n    catch (err) { return el(\'span\'); }\n  }\n\n  function relative(ts) {\n    const diff = Date.now() - ts;\n    const mins = Math.round(diff / 60000);\n    if (mins < 1) return \'just now\';\n    if (mins < 60) return mins + (mins === 1 ? \' minute ago\' : \' minutes ago\');\n    const hours = Math.round(mins / 60);\n    if (hours < 24) return hours + (hours === 1 ? \' hour ago\' : \' hours ago\');\n    const days = Math.round(hours / 24);\n    if (days < 31) return days + (days === 1 ? \' day ago\' : \' days ago\');\n    try { return new Date(ts).toLocaleDateString(undefined, { day: \'numeric\', month: \'long\', year: \'numeric\' }); }\n    catch (err) { return new Date(ts).toDateString(); }\n  }\n\n  function shell() {\n    root = el(\'div.guest#nd-guest\');\n\n    /* --- the bar across the top --- */\n    const bar = el(\'header.guest-bar\');\n\n    const brand = el(\'a.guest-brand\', { href: appBase(), title: \'Nodalis\' });\n    brand.appendChild(mark());\n    brand.appendChild(el(\'span.guest-brand-name\', null, \'Nodalis\'));\n    bar.appendChild(brand);\n\n    bar.appendChild(el(\'span.guest-bar-spacer\'));\n\n    const progress = el(\'div.guest-progress#nd-guest-progress\', { \'aria-hidden\': \'true\' });\n    progress.appendChild(el(\'span.guest-progress-fill#nd-guest-progress-fill\'));\n\n    /* Theme, which is the reader\'s alone. */\n    const themeBtn = el(\'button.guest-chip\', { type: \'button\', title: \'Choose a theme for yourself\' });\n    themeBtn.appendChild(icon(\'palette\', 15));\n    themeBtn.appendChild(el(\'span#nd-guest-theme-label\', null, STYLE_LABELS[prefs().style]));\n    themeBtn.addEventListener(\'click\', cycleStyle);\n    bar.appendChild(themeBtn);\n\n    const modeBtn = el(\'button.guest-icon\', { type: \'button\', title: \'Light or dark\', \'aria-label\': \'Light or dark\' });\n    modeBtn.appendChild(icon(\'contrast\', 16));\n    modeBtn.addEventListener(\'click\', cycleMode);\n    bar.appendChild(modeBtn);\n\n    const refreshBtn = el(\'button.guest-icon#nd-guest-refresh\', { type: \'button\', title: \'Check for changes\', \'aria-label\': \'Check for changes\' });\n    refreshBtn.appendChild(icon(\'refresh\', 16));\n    refreshBtn.addEventListener(\'click\', function () { reload(true); });\n    bar.appendChild(refreshBtn);\n\n    const menuBtn = el(\'button.guest-icon\', { type: \'button\', title: \'More\', \'aria-label\': \'More\' });\n    menuBtn.appendChild(icon(\'more\', 16));\n    menuBtn.addEventListener(\'click\', openMenu);\n    bar.appendChild(menuBtn);\n\n    root.appendChild(bar);\n    root.appendChild(progress);\n\n    /* --- the note --- */\n    const main = el(\'main.guest-main#nd-guest-main\');\n    main.appendChild(el(\'div.guest-loading\', null, \'Loading the note…\'));\n    root.appendChild(main);\n\n    document.body.appendChild(root);\n  }\n\n  /** The Nodalis mark, drawn inline so the reader needs nothing else. */\n  function mark() {\n    const NS = \'http://www.w3.org/2000/svg\';\n    const svg = document.createElementNS(NS, \'svg\');\n    svg.setAttribute(\'viewBox\', \'0 0 24 24\');\n    svg.setAttribute(\'width\', \'20\');\n    svg.setAttribute(\'height\', \'20\');\n    svg.setAttribute(\'class\', \'guest-mark\');\n    const path = document.createElementNS(NS, \'path\');\n    path.setAttribute(\'d\', \'M12 2.6 20 7.3v9.4L12 21.4 4 16.7V7.3zM12 2.6v18.8M4 7.3l16 9.4M20 7.3 4 16.7\');\n    path.setAttribute(\'fill\', \'none\');\n    path.setAttribute(\'stroke\', \'currentColor\');\n    path.setAttribute(\'stroke-width\', \'1.5\');\n    path.setAttribute(\'stroke-linejoin\', \'round\');\n    svg.appendChild(path);\n    return svg;\n  }\n\n  function cycleStyle() {\n    const p = prefs();\n    const next = STYLES[(STYLES.indexOf(p.style) + 1) % STYLES.length];\n    savePrefs({ style: next });\n  }\n\n  /*\n   * A light/dark button must change something visible on the first press. A\n   * plain auto -> light -> dark cycle does not: if the system is already light,\n   * the first press looks broken. So from auto it jumps to the OPPOSITE of\n   * what is currently showing, and auto comes back round at the end.\n   */\n  function cycleMode() {\n    const p = prefs();\n    if (p.mode === \'auto\') {\n      savePrefs({ mode: resolveMode(\'auto\') === \'dark\' ? \'light\' : \'dark\' });\n    } else if (p.mode === \'light\') {\n      savePrefs({ mode: \'dark\' });\n    } else {\n      savePrefs({ mode: \'auto\' });\n    }\n  }\n\n  function openMenu() {\n    const p = prefs();\n    const sheet = el(\'div.guest-sheet\');\n    const panel = el(\'div.guest-sheet-panel\');\n    panel.appendChild(el(\'div.guest-sheet-grip\'));\n    panel.appendChild(el(\'div.guest-sheet-title\', null, \'Reading options\'));\n\n    const close = function () {\n      sheet.classList.remove(\'is-in\');\n      setTimeout(function () { if (sheet.parentNode) sheet.remove(); }, 200);\n    };\n\n    const row = function (label, sub, iconName, fn) {\n      const b = el(\'button.guest-sheet-item\', { type: \'button\' });\n      b.appendChild(icon(iconName, 18));\n      const col = el(\'div.guest-sheet-main\');\n      col.appendChild(el(\'div.guest-sheet-label\', null, label));\n      if (sub) col.appendChild(el(\'div.guest-sheet-desc\', null, sub));\n      b.appendChild(col);\n      b.addEventListener(\'click\', function () { fn(); close(); });\n      return b;\n    };\n\n    STYLES.forEach(function (s) {\n      panel.appendChild(row(STYLE_LABELS[s], s === p.style ? \'Current theme\' : \'\', \'palette\',\n        function () { savePrefs({ style: s }); }));\n    });\n    panel.appendChild(el(\'div.guest-sheet-sep\'));\n    panel.appendChild(row(p.width === \'wide\' ? \'Narrower column\' : \'Wider column\',\n      \'Line length while reading\', \'columns\',\n      function () { savePrefs({ width: p.width === \'wide\' ? \'comfortable\' : \'wide\' }); }));\n    panel.appendChild(row(\'Print or save as PDF\', \'\', \'file\', function () { window.print(); }));\n    panel.appendChild(row(\'Copy this link\', \'\', \'link\', function () { copyLink(); }));\n    panel.appendChild(row(\'Make notes of my own\', \'Open Nodalis - free, no account\', \'sparkle\',\n      function () { location.href = appBase(); }));\n\n    sheet.appendChild(panel);\n    sheet.addEventListener(\'click\', function (e) { if (e.target === sheet) close(); });\n    document.body.appendChild(sheet);\n    requestAnimationFrame(function () { sheet.classList.add(\'is-in\'); });\n  }\n\n  async function copyLink() {\n    const url = linkFor(gistId);\n    try {\n      await navigator.clipboard.writeText(url);\n      flash(\'Link copied.\');\n    } catch (err) {\n      flash(url);\n    }\n  }\n\n  function flash(text) {\n    const old = document.getElementById(\'nd-guest-flash\');\n    if (old) old.remove();\n    const node = el(\'div.guest-flash#nd-guest-flash\', null, text);\n    document.body.appendChild(node);\n    requestAnimationFrame(function () { node.classList.add(\'is-in\'); });\n    setTimeout(function () {\n      node.classList.remove(\'is-in\');\n      setTimeout(function () { if (node.parentNode) node.remove(); }, 300);\n    }, 2600);\n  }\n\n  /* ----------------------------------------------------------------- render */\n\n  function renderNote() {\n    const main = document.getElementById(\'nd-guest-main\');\n    if (!main || !doc) return;\n    main.textContent = \'\';\n\n    const article = el(\'article.guest-article\');\n\n    const head = el(\'div.guest-head\');\n    head.appendChild(el(\'h1.guest-title\', null, doc.title));\n    const meta = el(\'div.guest-meta\');\n    meta.appendChild(el(\'span\', null, \'Shared note\'));\n    meta.appendChild(el(\'span.guest-dot\', null, \'·\'));\n    meta.appendChild(el(\'span#nd-guest-updated\', null, \'Updated \' + relative(doc.updatedAt)));\n    head.appendChild(meta);\n    article.appendChild(head);\n\n    const body = el(\'div.guest-body.prose\');\n    try {\n      body.innerHTML = N.markdown.render(doc.markdown, { depth: 1, headingAnchors: false });\n    } catch (err) {\n      body.appendChild(el(\'pre\', null, doc.markdown));\n    }\n    // Nothing in a shared note may navigate the reader into a vault that does\n    // not exist here, so unresolved wikilinks become plain text.\n    body.querySelectorAll(\'a[data-wikilink], a.is-unresolved, a[href^="#note"]\').forEach(function (a) {\n      const span = el(\'span.guest-plainlink\', null, a.textContent);\n      a.replaceWith(span);\n    });\n    body.querySelectorAll(\'a[href]\').forEach(function (a) {\n      a.setAttribute(\'target\', \'_blank\');\n      a.setAttribute(\'rel\', \'noopener nofollow\');\n    });\n    // Checkboxes in a shared note are a picture of the author\'s list, not a\n    // control the reader gets to change.\n    body.querySelectorAll(\'input[type="checkbox"]\').forEach(function (box) { box.disabled = true; });\n    article.appendChild(body);\n\n    const toc = buildToc(body);\n    if (toc) article.insertBefore(toc, body);\n\n    const foot = el(\'footer.guest-foot\');\n    const cta = el(\'div.guest-cta\');\n    cta.appendChild(el(\'div.guest-cta-title\', null, \'Written in Nodalis\'));\n    cta.appendChild(el(\'p.guest-cta-text\', null,\n      \'Notes that link to each other, on your own device, in plain markdown files you keep. No account needed.\'));\n    const actions = el(\'div.guest-cta-actions\');\n    const open = el(\'a.guest-btn.is-primary\', { href: appBase() }, \'Make notes of my own\');\n    actions.appendChild(open);\n    const install = el(\'button.guest-btn#nd-guest-install\', { type: \'button\', hidden: \'hidden\' }, \'Install the app\');\n    install.addEventListener(\'click\', runInstall);\n    actions.appendChild(install);\n    cta.appendChild(actions);\n    foot.appendChild(cta);\n    article.appendChild(foot);\n\n    main.appendChild(article);\n    wireProgress(main);\n    wireInstall();\n  }\n\n  /** An outline, but only when the note is long enough to need one. */\n  function buildToc(body) {\n    const heads = Array.prototype.slice.call(body.querySelectorAll(\'h2, h3\'));\n    if (heads.length < 3) return null;\n    const nav = el(\'nav.guest-toc\', { \'aria-label\': \'On this page\' });\n    nav.appendChild(el(\'div.guest-toc-title\', null, \'On this page\'));\n    const list = el(\'ul.guest-toc-list\');\n    heads.forEach(function (h, i) {\n      if (!h.id) h.id = \'nd-h-\' + i;\n      const li = el(\'li\' + (h.tagName === \'H3\' ? \'.is-sub\' : \'\'));\n      const a = el(\'a\', { href: \'#\' + h.id }, h.textContent);\n      a.addEventListener(\'click\', function (e) {\n        e.preventDefault();\n        h.scrollIntoView({ behavior: \'smooth\', block: \'start\' });\n      });\n      li.appendChild(a);\n      list.appendChild(li);\n    });\n    nav.appendChild(list);\n    return nav;\n  }\n\n  function wireProgress(scroller) {\n    const fill = document.getElementById(\'nd-guest-progress-fill\');\n    if (!fill) return;\n    const update = function () {\n      const max = scroller.scrollHeight - scroller.clientHeight;\n      const pct = max > 20 ? Math.min(1, Math.max(0, scroller.scrollTop / max)) : 0;\n      fill.style.transform = \'scaleX(\' + pct.toFixed(4) + \')\';\n    };\n    scroller.addEventListener(\'scroll\', update, { passive: true });\n    update();\n  }\n\n  /* ---------------------------------------------------------------- install */\n\n  /*\n   * The head snippet already parks `beforeinstallprompt` on window, for the\n   * app\'s own install card. Guest mode reuses exactly that, so a reader who\n   * likes what they see can install without ever opening the app first.\n   */\n  function wireInstall() {\n    const btn = document.getElementById(\'nd-guest-install\');\n    if (!btn) return;\n    const show = function () { btn.hidden = false; };\n    if (window.__ndInstallPrompt) show();\n    window.addEventListener(\'beforeinstallprompt\', function (e) {\n      e.preventDefault();\n      window.__ndInstallPrompt = e;\n      show();\n    });\n  }\n\n  async function runInstall() {\n    const prompt = window.__ndInstallPrompt;\n    if (!prompt) { flash(\'Use your browser menu, then "Install" or "Add to Home Screen".\'); return; }\n    try {\n      prompt.prompt();\n      const choice = await prompt.userChoice;\n      window.__ndInstallPrompt = null;\n      const btn = document.getElementById(\'nd-guest-install\');\n      if (btn) btn.hidden = true;\n      if (choice && choice.outcome === \'accepted\') flash(\'Installed.\');\n    } catch (err) {\n      flash(\'That did not work. Your browser menu will have an Install option.\');\n    }\n  }\n\n  /* ------------------------------------------------------------ load / error */\n\n  function showError(err) {\n    const main = document.getElementById(\'nd-guest-main\');\n    if (!main) return;\n    main.textContent = \'\';\n    const box = el(\'div.guest-error\');\n    box.appendChild(icon(err && err.code === \'gone\' ? \'link-off\' : \'warning\', 30));\n    box.appendChild(el(\'div.guest-error-title\', null,\n      err && err.code === \'gone\' ? \'This note is not shared any more\' : \'Could not load the note\'));\n    box.appendChild(el(\'p.guest-error-text\', null, (err && err.message) || \'Something went wrong.\'));\n    const again = el(\'button.guest-btn\', { type: \'button\' }, \'Try again\');\n    again.addEventListener(\'click\', function () { reload(true); });\n    box.appendChild(again);\n    const home = el(\'a.guest-btn.is-primary\', { href: appBase() }, \'Open Nodalis\');\n    box.appendChild(home);\n    main.appendChild(box);\n  }\n\n  async function reload(announce) {\n    const btn = document.getElementById(\'nd-guest-refresh\');\n    if (btn) btn.classList.add(\'is-spinning\');\n    try {\n      const next = await fetchNote(gistId);\n      const changed = lastFetchedText !== null && next.markdown !== lastFetchedText;\n      lastFetchedText = next.markdown;\n      doc = next;\n      if (changed) {\n        /*\n         * Do not swap the text out from under someone mid-sentence. Tell them,\n         * and let them take the update when they are ready.\n         */\n        showUpdateBanner();\n      } else {\n        renderNote();\n        if (announce) flash(\'This is the latest version.\');\n      }\n    } catch (err) {\n      if (!doc) showError(err);\n      else if (announce) flash((err && err.message) || \'Could not check for changes.\');\n    } finally {\n      if (btn) btn.classList.remove(\'is-spinning\');\n    }\n  }\n\n  function showUpdateBanner() {\n    if (document.getElementById(\'nd-guest-update\')) return;\n    const bar = el(\'div.guest-update#nd-guest-update\');\n    bar.appendChild(el(\'span\', null, \'The author has updated this note.\'));\n    const btn = el(\'button.guest-update-btn\', { type: \'button\' }, \'Show the new version\');\n    btn.addEventListener(\'click\', function () {\n      bar.remove();\n      renderNote();\n      const main = document.getElementById(\'nd-guest-main\');\n      if (main) main.scrollTop = 0;\n      flash(\'Updated.\');\n    });\n    bar.appendChild(btn);\n    root.appendChild(bar);\n    requestAnimationFrame(function () { bar.classList.add(\'is-in\'); });\n  }\n\n  /* -------------------------------------------------------------------- boot */\n\n  function boot() {\n    gistId = idFromHash();\n    document.documentElement.dataset.guest = \'1\';\n    document.body.dataset.guest = \'1\';\n\n    // The app shell is in the document but must never be seen or reachable.\n    const app = document.getElementById(\'app\');\n    if (app) app.remove();\n    [\'mobile-nav\', \'scrim\'].forEach(function (id) {\n      const n2 = document.getElementById(id);\n      if (n2) n2.remove();\n    });\n\n    applyPrefs();\n    try { if (N.icons && N.icons.hydrate) N.icons.hydrate(document); } catch (err) { /* fine */ }\n    shell();\n    // Nothing has been painted until now, so release the boot curtain here too.\n    document.documentElement.removeAttribute(\'data-boot\');\n\n    if (!gistId) { showError(new Error(\'That link is missing its note id.\')); return; }\n\n    reload(false);\n\n    // Follow the author\'s edits without the reader doing anything.\n    window.addEventListener(\'focus\', function () { reload(false); });\n    document.addEventListener(\'visibilitychange\', function () {\n      if (!document.hidden) reload(false);\n    });\n    try {\n      window.matchMedia(\'(prefers-color-scheme: dark)\')\n        .addEventListener(\'change\', function () { if (prefs().mode === \'auto\') applyPrefs(); });\n    } catch (err) { /* older Safari */ }\n    window.addEventListener(\'hashchange\', function () {\n      const next = idFromHash();\n      if (next && next !== gistId) { gistId = next; doc = null; lastFetchedText = null; reload(false); }\n    });\n  }\n\n  N.guest = {\n    wanted: wanted, boot: boot, linkFor: linkFor, appBase: appBase,\n    prefs: prefs, savePrefs: savePrefs, fetchNote: fetchNote,\n    stripFrontMatter: stripFrontMatter, dropDuplicateTitle: dropDuplicateTitle,\n  };\n})(window.NODALIS = window.NODALIS || {});'

MODULE_ANCHOR = "/* ===== js/app.js ===== */"
ALREADY_MARKER = "js/features/guest.js"
EXPECTED_MARKERS = [
    "js/features/share.js",
    "js/features/notemeta.js",
    "function installSheetDrag",
]


def fail(msg):
    sys.stderr.write("\n" + "=" * 72 + "\nSTOPPED - nothing was written.\n\n" + msg + "\n"
                     + "=" * 72 + "\n")
    sys.exit(1)


def main():
    if len(sys.argv) < 2:
        fail("Tell me where your index.html is:\n\n"
             "    python3 apply-nodalis-v6-fixes.py index.html")
    path = sys.argv[1]
    if not os.path.isfile(path):
        fail("There is no file at: " + path)

    src = io.open(path, encoding="utf-8").read()

    if ALREADY_MARKER in src:
        fail("This file already has the v6 changes.\n"
             "Run it on your pre-v6 index.html, or restore index.html.bak first.")

    missing = [m for m in EXPECTED_MARKERS if m not in src]
    if missing:
        fail("This does not look like the index.html these changes were built for.\n"
             "It should be the file produced by apply-nodalis-v5-fixes.py.\n\n"
             "Could not find: " + "; ".join(missing))

    problems = []
    for label, old, new in EDITS:
        n = src.count(old)
        if n != 1:
            problems.append("    %-56s found %d times, expected 1" % (label, n))
    if src.count(MODULE_ANCHOR) != 1:
        problems.append("    %-56s found %d times, expected 1"
                        % ("where the new module goes", src.count(MODULE_ANCHOR)))
    if problems:
        fail("Some changes did not match your file:\n\n" + "\n".join(problems) +
             "\n\nThat usually means the file was edited by hand since the last patch.\n"
             "Send me the file and I will rebuild this for it.")

    out = src
    for label, old, new in EDITS:
        out = out.replace(old, new, 1)
        print("  ok   " + label)
    out = out.replace(MODULE_ANCHOR, MODULES_JS.rstrip() + "\n\n" + MODULE_ANCHOR, 1)
    print("  ok   the shared-reader module")

    backup = path + ".bak"
    shutil.copy2(path, backup)
    io.open(path, "w", encoding="utf-8", newline="").write(out)

    print("")
    print("  " + "-" * 66)
    print("  Done. %d changes + 1 module." % len(EDITS))
    print("  Updated : %s   (+%s bytes)" % (path, format(len(out) - len(src), ",")))
    print("  Backup  : %s" % backup)
    print("  " + "-" * 66)
    print("")
    print("  TRY THESE FIRST")
    print("    * Reload. No flash of the empty app, and the folder should")
    print("      already be connected without a click.")
    print("    * Open a note, then Share... > Publish and get a link.")
    print("      Open that link in a private window - that is the reader.")
    print("    * On a phone, drag any bottom sheet down with your finger.")
    print("    * Press the '...' in the top bar. It opens under the button.")
    print("")
    print("  ONE THING TO CHECK: publishing needs your GitHub token to have")
    print("  the 'gist' tick box, which is separate from Contents.")
    print("")


if __name__ == "__main__":
    main()
